SELECT t_work_item.*, t_work_item_type.type_name AS work_item_type_name
FROM t_work_item
LEFT JOIN t_work_item_type ON t_work_item.work_item_type_id = t_work_item_type.work_item_type_id

    t_work_item.deleted_flag = #{queryForm.deletedFlag}

        AND t_work_item.work_item_type_id = #{queryForm.workItemTypeId}


        AND (INSTR(t_work_item.work_item_name, #{queryForm.keywords})
        OR INSTR(t_work_item.description, #{queryForm.keywords})
        OR INSTR(t_work_item.score_standard, #{queryForm.keywords}))


        AND t_work_item.disabled_flag = #{queryForm.disabledFlag}



    ORDER BY t_work_item.sort ASC, t_work_item.work_item_id DESC

SELECT t_work_item.*, t_work_item_type.type_name AS work_item_type_name
FROM t_work_item
LEFT JOIN t_work_item_type ON t_work_item.work_item_type_id = t_work_item_type.work_item_type_id

    t_work_item.deleted_flag = #{deletedFlag}

        AND t_work_item.work_item_type_id = #{workItemTypeId}


        AND (INSTR(t_work_item.work_item_name, #{keywords})
        OR INSTR(t_work_item.description, #{keywords})
        OR INSTR(t_work_item.score_standard, #{keywords}))


        AND t_work_item.disabled_flag = #{disabledFlag}


ORDER BY t_work_item.sort ASC, t_work_item.work_item_id DESC

SELECT t_work_item.*, t_work_item_type.type_name AS work_item_type_name
FROM t_work_item
LEFT JOIN t_work_item_type ON t_work_item.work_item_type_id = t_work_item_type.work_item_type_id
