SELECT *
FROM t_work_item
WHERE work_item_type_id = #{workItemTypeId}
AND work_item_name = #{workItemName}
AND deleted_flag = #{deletedFlag}

    AND work_item_id != #{excludeId}

SELECT COUNT(1)
FROM t_work_item
WHERE work_item_type_id = #{workItemTypeId}
AND deleted_flag = #{deletedFlag}

